const $ = s => document.querySelector(s);
const chapters = [...document.querySelectorAll('main > section')];
const navLinks = [...document.querySelectorAll('nav a')];
const menu = $('.mobile-menu'), sidebar = $('#sidebar');
menu.addEventListener('click',()=>{const open=sidebar.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar índice':'Abrir índice');});
navLinks.forEach(a=>a.addEventListener('click',()=>{sidebar.classList.remove('open');menu.setAttribute('aria-expanded','false');}));
document.addEventListener('click',e=>{if(!sidebar.contains(e.target)&&!menu.contains(e.target)){sidebar.classList.remove('open');menu.setAttribute('aria-expanded','false');}});
let scrollPending=false;
function updateActive(){let active=chapters[0].id;for(const s of chapters)if(s.getBoundingClientRect().top<180)active=s.id;for(const a of navLinks){const yes=a.hash===`#${active}`;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');}scrollPending=false;}
addEventListener('scroll',()=>{if(!scrollPending){scrollPending=true;requestAnimationFrame(updateActive);}}, {passive:true});updateActive();
const dialog=$('#search-dialog'),search=$('#manual-search'),results=$('#search-results');
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const searchIndex=chapters.map(s=>({id:s.id,title:s.querySelector('h1,h2').innerText.replace(/\n/g,' '),text:s.textContent.replace(/\s+/g,' ')}));
function openSearch(){dialog.showModal();document.body.classList.add('dialog-open');search.focus();}
$('.search-open').addEventListener('click',openSearch);$('#close-search').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)&&!dialog.open){e.preventDefault();openSearch();}});
search.addEventListener('input',()=>{results.replaceChildren();const q=normalize(search.value.trim());if(!q){$('#search-count').textContent='Escribe para encontrar una sección.';return;}const matches=searchIndex.filter(s=>normalize(s.text).includes(q));$('#search-count').textContent=`${matches.length} ${matches.length===1?'sección encontrada':'secciones encontradas'}`;for(const s of matches){const a=document.createElement('a');a.href=`#${s.id}`;const b=document.createElement('b');b.textContent=s.title;const p=document.createElement('p');const index=normalize(s.text).indexOf(q),start=Math.max(0,index-45);p.textContent=(start?'…':'')+s.text.slice(start,start+180)+'…';a.append(b,p);a.addEventListener('click',()=>{dialog.close();const section=document.getElementById(s.id);section.querySelectorAll('details').forEach(d=>{if(normalize(d.textContent).includes(q))d.open=true;});});results.append(a);}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('#commands article').forEach(a=>a.hidden=filter!=='all'&&a.dataset.category!==filter);}));
$('#print-manual').addEventListener('click',()=>{const states=[...document.querySelectorAll('details')].map(d=>[d,d.open]);document.querySelectorAll('details').forEach(d=>d.open=true);const restore=()=>{states.forEach(([d,open])=>d.open=open);removeEventListener('afterprint',restore);};addEventListener('afterprint',restore);window.print();});
let world,exploring=false,exploded=false;
async function loadModel(){try{const {createWorld}=await import('./scene.js');world=await createWorld({host:$('#model-host'),onReady(){ $('#model-fallback').classList.add('hidden');$('#model-status').className='ready';$('#model-status').textContent='Modelo 3D listo. Puedes explorar y ver el despiece.';},onError(){ $('#model-fallback').classList.remove('hidden');$('#model-status').className='error';$('#model-status').textContent='Vista ilustrada disponible. El 3D requiere WebGL 2 y un navegador compatible.';document.querySelectorAll('.model-controls button,.focus-link').forEach(b=>b.disabled=true);},onFocus({label,detail}){$('#model-caption').textContent=`${label} · ${detail}`;},onSelect({name,detail}){$('#model-caption').textContent=`${name} · ${detail}`;}});window.ariaManualModel=world;}catch(e){$('#model-status').className='error';$('#model-status').textContent='Vista ilustrada del CNC. No se pudo cargar el visor 3D.';document.querySelectorAll('.model-controls button,.focus-link').forEach(b=>b.disabled=true);}}
$('#explore').addEventListener('click',()=>{if(!world)return;exploring=!exploring;world.setExploring(exploring);$('#explore').setAttribute('aria-pressed',String(exploring));$('#explore').textContent=exploring?'↔ Salir de explorar':'↔ Explorar 3D';});
$('#explode').addEventListener('click',()=>{if(!world)return;exploded=!exploded;world.setExploded(exploded);$('#explode').setAttribute('aria-pressed',String(exploded));});
$('#reset-model').addEventListener('click',()=>{world?.reset();exploring=exploded=false;$('#explore').setAttribute('aria-pressed','false');$('#explore').textContent='↔ Explorar 3D';$('#explode').setAttribute('aria-pressed','false');});
document.querySelectorAll('[data-focus]').forEach(button=>button.addEventListener('click',()=>{world?.focusTopic(button.dataset.focus);exploring=false;$('#explore').setAttribute('aria-pressed','false');$('#explore').textContent='↔ Explorar 3D';$('#inicio').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
loadModel();
